local RS = game:GetService('ReplicatedStorage')
local SSS = game:GetService('ServerScriptService')
local SG = game:GetService('StarterGui')
local SP = game:GetService('StarterPlayer')
local function ensureFolder(parent, name)
  local f = parent:FindFirstChild(name)
  if not f then f = Instance.new('Folder') f.Name = name f.Parent = parent end
  return f
end
local function ensureModule(parent, name, className, content)
  local m = parent:FindFirstChild(name)
  if not m then m = Instance.new(className) m.Name = name m.Parent = parent end
  m.Source = content
  print('OK: ' .. name)
end
ensureFolder(RS, 'Modules')
ensureFolder(RS:WaitForChild('Modules'), 'Weapon')
ensureFolder(SSS, 'Server')
ensureFolder(SSS:WaitForChild('Server'), 'System')
ensureFolder(SSS:WaitForChild('Server'):WaitForChild('System'), 'Weapon')
ensureFolder(SG, 'MainMenu')
ensureFolder(SP, 'StarterPlayerScripts')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'DoorSystem', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal TweenService = game:GetService("TweenService")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\n\nlocal DoorSystem = {}\nDoorSystem.__index = DoorSystem\n\nlocal doorInstances = {}\nlocal doorStates = {}\n\nfunction DoorSystem:Init()\n	for _, obj in ipairs(workspace:GetDescendants()) do\n		if obj:IsA("Model") and obj:GetAttribute("DoorType") then\n			self:RegisterDoor(obj)\n		end\n	end\n\n	workspace.DescendantAdded:Connect(function(obj)\n		if obj:IsA("Model") and obj:GetAttribute("DoorType") then\n			self:RegisterDoor(obj)\n		end\n	end)\nend\n\nfunction DoorSystem:RegisterDoor(doorModel)\n	local doorType = doorModel:GetAttribute("DoorType")\n	local roomId = doorModel:GetAttribute("RoomId")\n	local cardRequired = doorModel:GetAttribute("CardRequired")\n\n	local config = Config.DoorTypes[doorType]\n	if not config then return end\n\n	doorInstances[doorModel:GetFullName()] = {\n		model = doorModel,\n		config = config,\n		roomId = roomId,\n		cardRequired = cardRequired,\n	}\n\n	doorStates[doorModel:GetFullName()] = {\n		open = false,\n		locked = false,\n		cooldown = false,\n	}\nend\n\nfunction DoorSystem:CanOpen(player, doorKey)\n	local doorData = doorInstances[doorKey]\n	local state = doorStates[doorKey]\n	if not doorData or not doorData.model then return false end\n	if state.locked then return false end\n	if state.cooldown then return false end\n\n	local playerCard = player:GetAttribute("CurrentCard")\n	if not playerCard then return false end\n\n	local cardData = Config.CardPermissions[playerCard]\n	if not cardData then return false end\n\n	local doorType = doorData.model:GetAttribute("DoorType")\n	if doorType == "Regular" or doorType == "Armored" or doorType == "Hermetic" then\n		local allowedDoors = cardData.openDoors or {}\n		local doorTypeName = doorData.model:GetAttribute("DoorTypeName")\n		if not table.find(allowedDoors, doorTypeName) then\n			return false\n		end\n	end\n\n	if cardData.blockedRooms and doorData.roomId then\n		if table.find(cardData.blockedRooms, doorData.roomId) then\n			return false\n		end\n	end\n\n	if cardData.factionLock then\n		local playerFaction = player:GetAttribute("Faction")\n		if playerFaction ~= cardData.factionLock then\n			return false\n		end\n	end\n\n	return true\nend\n\nfunction DoorSystem:Open(doorKey)\n	local doorData = doorInstances[doorKey]\n	local state = doorStates[doorKey]\n	if not doorData or state.open then return end\n\n	state.open = true\n	state.cooldown = true\n\n	local doorModel = doorData.model\n	local config = doorData.config\n\n	if config.animationType == "swing" then\n		local pivot = doorModel.PrimaryPart\n		if pivot then\n			local hinge = doorModel:FindFirstChild("Hinge")\n			if hinge then\n				pivot = hinge\n			end\n			local tweenInfo = TweenInfo.new(config.openSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n			local goal = {CFrame = pivot.CFrame * CFrame.Angles(0, math.rad(config.openAngle), 0)}\n			local tween = TweenService:Create(pivot, tweenInfo, goal)\n			tween:Play()\n		end\n	elseif config.animationType == "slide_up" then\n		for _, part in ipairs(doorModel:GetDescendants()) do\n			if part:IsA("BasePart") and part:GetAttribute("IsDoor") then\n				local tweenInfo = TweenInfo.new(config.openSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n				local goal = {CFrame = part.CFrame + config.openOffset}\n				local tween = TweenService:Create(part, tweenInfo, goal)\n				tween:Play()\n			end\n		end\n	end\n\n	task.delay(5, function()\n		state.cooldown = false\n	end)\nend\n\nfunction DoorSystem:Close(doorKey)\n	local doorData = doorInstances[doorKey]\n	local state = doorStates[doorKey]\n	if not doorData or not state.open then return end\n\n	state.open = false\n	state.cooldown = true\n\n	local doorModel = doorData.model\n	local config = doorData.config\n\n	if config.animationType == "swing" then\n		local pivot = doorModel.PrimaryPart\n		if pivot then\n			local hinge = doorModel:FindFirstChild("Hinge")\n			if hinge then\n				pivot = hinge\n			end\n			local tweenInfo = TweenInfo.new(config.openSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n			local goal = {CFrame = pivot.CFrame * CFrame.Angles(0, math.rad(-config.openAngle), 0)}\n			local tween = TweenService:Create(pivot, tweenInfo, goal)\n			tween:Play()\n		end\n	elseif config.animationType == "slide_up" then\n		for _, part in ipairs(doorModel:GetDescendants()) do\n			if part:IsA("BasePart") and part:GetAttribute("IsDoor") then\n				local tweenInfo = TweenInfo.new(config.openSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n				local goal = {CFrame = part.CFrame - config.openOffset}\n				local tween = TweenService:Create(part, tweenInfo, goal)\n				tween:Play()\n			end\n		end\n	end\n\n	task.delay(5, function()\n		state.cooldown = false\n	end)\nend\n\nfunction DoorSystem:LockDoor(doorKey)\n	local state = doorStates[doorKey]\n	if state then\n		state.locked = true\n	end\nend\n\nfunction DoorSystem:UnlockDoor(doorKey)\n	local state = doorStates[doorKey]\n	if state then\n		state.locked = false\n	end\nend\n\nfunction DoorSystem:LockAllByType(doorTypeName)\n	for key, data in pairs(doorInstances) do\n		if data.model:GetAttribute("DoorTypeName") == doorTypeName then\n			DoorSystem:LockDoor(key)\n		end\n	end\nend\n\nfunction DoorSystem:UnlockAllByType(doorTypeName)\n	for key, data in pairs(doorInstances) do\n		if data.model:GetAttribute("DoorTypeName") == doorTypeName then\n			DoorSystem:UnlockDoor(key)\n		end\n	end\nend\n\nfunction DoorSystem:GetDoorKey(doorModel)\n	return doorModel:GetFullName()\nend\n\nreturn DoorSystem\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'RoleSystem', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Players = game:GetService("Players")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\n\nlocal RoleSystem = {}\nRoleSystem.__index = RoleSystem\n\nlocal playerRoles = {}\n\nfunction RoleSystem:SetRole(player, roleId, isFaction)\n	local roleData\n	if isFaction then\n		roleData = Config.FactionRoles[roleId]\n	else\n		roleData = Config.Roles[roleId]\n	end\n\n	if not roleData then return false, "Роль не найдена" end\n\n	if not isFaction then\n		local DataStore = require(ReplicatedStorage.Modules.DataStore)\n		local data = DataStore:Get(player)\n		if not data then return false, "Данные не загружены" end\n\n		if data.firedRoles[roleId] then\n			return false, "Вы уволены с этой роли"\n		end\n\n		if data.minutes < roleData.minutes then\n			return false, "Недостаточно минут"\n		end\n	end\n\n	if roleData.faction then\n		local factionConfig = Config.Factions[roleData.faction]\n		if factionConfig and factionConfig.groupId > 0 then\n			local success, rank = pcall(function()\n				return Players:GetRankInGroup(player, factionConfig.groupId)\n			end)\n			if not success or rank == 0 then\n				return false, "Вы не состоите в группе фракции"\n			end\n		end\n	end\n\n	player:SetAttribute("CurrentRole", roleId)\n	player:SetAttribute("CurrentCard", roleData.card)\n	player:SetAttribute("AccessLevel", roleData.accessLevel)\n\n	if roleData.faction then\n		player:SetAttribute("Faction", roleData.faction)\n	end\n\n	playerRoles[player.UserId] = {\n		roleId = roleId,\n		isFaction = isFaction,\n		faction = roleData.faction,\n	}\n\n	return true, "Роль назначена"\nend\n\nfunction RoleSystem:RemoveRole(player)\n	player:SetAttribute("CurrentRole", nil)\n	player:SetAttribute("CurrentCard", nil)\n	player:SetAttribute("AccessLevel", 0)\n	player:SetAttribute("Faction", nil)\n	playerRoles[player.UserId] = nil\nend\n\nfunction RoleSystem:GetRole(player)\n	return playerRoles[player.UserId]\nend\n\nfunction RoleSystem:GetAvailableRoles(player)\n	local DataStore = require(ReplicatedStorage.Modules.DataStore)\n	local data = DataStore:Get(player)\n	if not data then return {} end\n\n	local available = {}\n	for roleId, roleData in pairs(Config.Roles) do\n		if data.minutes >= roleData.minutes and not data.firedRoles[roleId] then\n			table.insert(available, {\n				id = roleId,\n				displayName = roleData.displayName,\n				requiredMinutes = roleData.minutes,\n			})\n		end\n	end\n	return available\nend\n\nfunction RoleSystem:GetAvailableFactionRoles(player)\n	local available = {}\n	for roleId, roleData in pairs(Config.FactionRoles) do\n		local factionConfig = Config.Factions[roleData.faction]\n		local groupId = factionConfig and factionConfig.groupId or 0\n		local include = false\n		if groupId > 0 then\n			local success, rank = pcall(function()\n				return Players:GetRankInGroup(player, groupId)\n			end)\n			include = success and rank > 0\n		else\n			include = true\n		end\n		if include then\n			table.insert(available, {\n				id = roleId,\n				displayName = roleData.displayName,\n				faction = factionConfig and factionConfig.displayName or roleData.faction,\n			})\n		end\n	end\n	return available\nend\n\nfunction RoleSystem:GetPlayerMinutes(player)\n	local DataStore = require(ReplicatedStorage.Modules.DataStore)\n	local data = DataStore:Get(player)\n	return data and data.minutes or 0\nend\n\nfunction RoleSystem:OnPlayerAdded(player)\n	player:SetAttribute("CurrentRole", nil)\n	player:SetAttribute("CurrentCard", nil)\n	player:SetAttribute("AccessLevel", 0)\n	player:SetAttribute("Faction", nil)\n	player:SetAttribute("IsWanted", false)\nend\n\nfunction RoleSystem:OnPlayerRemoving(player)\n	playerRoles[player.UserId] = nil\nend\n\nreturn RoleSystem\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'ControlRoom', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Lighting = game:GetService("Lighting")\nlocal SoundService = game:GetService("SoundService")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\nlocal DoorSystem = require(script.Parent.DoorSystem)\n\nlocal ControlRoom = {}\nControlRoom.__index = ControlRoom\n\nlocal alarmActive = false\nlocal containmentLocked = false\nlocal experimentLocked = false\n\nfunction ControlRoom:ToggleAlarm(state)\n	alarmActive = state\n\n	local alarmLights = workspace:FindFirstChild("AlarmLights")\n	if alarmLights then\n		for _, light in ipairs(alarmLights:GetDescendants()) do\n			if light:IsA("PointLight") or light:IsA("SpotLight") then\n				light.Enabled = state\n				if state then\n					light.Color = Color3.fromRGB(255, 0, 0)\n				end\n			end\n		end\n	end\n\n	local siren = SoundService:FindFirstChild("Siren")\n	if siren then\n		if state then\n			siren:Play()\n		else\n			siren:Stop()\n		end\n	end\n\n	ReplicatedStorage:SetAttribute("AlarmActive", state)\nend\n\nfunction ControlRoom:ToggleContainment(state)\n	containmentLocked = state\n\n	if state then\n		DoorSystem:LockAllByType("Hermetic")\n	else\n		DoorSystem:UnlockAllByType("Hermetic")\n	end\n\n	ReplicatedStorage:SetAttribute("ContainmentLocked", state)\nend\n\nfunction ControlRoom:ToggleExperimentBlock(state)\n	experimentLocked = state\n\n	if state then\n		DoorSystem:LockAllByType("ExperimentDoor")\n	else\n		DoorSystem:UnlockAllByType("ExperimentDoor")\n	end\n\n	ReplicatedStorage:SetAttribute("ExperimentLocked", state)\nend\n\nfunction ControlRoom:GetState()\n	return {\n		alarmActive = alarmActive,\n		containmentLocked = containmentLocked,\n		experimentLocked = experimentLocked,\n	}\nend\n\nreturn ControlRoom\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'WantedSystem', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Players = game:GetService("Players")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\nlocal DataStore = require(ReplicatedStorage.Modules.DataStore)\n\nlocal WantedSystem = {}\nWantedSystem.__index = WantedSystem\n\nlocal wantedPlayers = {}\n\nfunction WantedSystem:DeclareWanted(targetPlayer, reporterPlayer, duration)\n	if not targetPlayer or not targetPlayer.Parent then return false, "Игрок не найден" end\n	if not reporterPlayer then return false, "Не указан инициатор" end\n\n	local targetData = DataStore:Get(targetPlayer)\n	if not targetData then return false, "Данные цели не загружены" end\n\n	duration = math.clamp(duration or Config.WANTED_DURATION, 0, Config.WANTED_DURATION)\n\n	DataStore:SetWanted(targetPlayer, true, duration)\n	targetPlayer:SetAttribute("IsWanted", true)\n	targetPlayer:SetAttribute("WantedLabel", true)\n\n	wantedPlayers[targetPlayer.UserId] = {\n		player = targetPlayer,\n		reporter = reporterPlayer,\n		timer = duration,\n		found = false,\n		kpzDuration = 0,\n	}\n\n	ReplicatedStorage:SetAttribute("WantedCount", ReplicatedStorage:GetAttribute("WantedCount") + 1)\n\n	return true, "Розыск объявлен"\nend\n\nfunction WantedSystem:RemoveWanted(targetPlayer)\n	local userId = targetPlayer.UserId\n	wantedPlayers[userId] = nil\n\n	DataStore:SetWanted(targetPlayer, false, 0)\n	targetPlayer:SetAttribute("IsWanted", false)\n	targetPlayer:SetAttribute("WantedLabel", false)\n\n	ReplicatedStorage:SetAttribute("WantedCount", ReplicatedStorage:GetAttribute("WantedCount") - 1)\nend\n\nfunction WantedSystem:ArrestPlayer(targetPlayer, captorPlayer, kpzDuration)\n	local entry = wantedPlayers[targetPlayer.UserId]\n	if not entry then return false, "Игрок не в розыске" end\n\n	kpzDuration = math.clamp(kpzDuration or 300, 0, Config.KPZ_MAX_DURATION)\n\n	entry.found = true\n	entry.kpzDuration = kpzDuration\n\n	targetPlayer:SetAttribute("InKPZ", true)\n	targetPlayer:SetAttribute("KPZTimer", kpzDuration)\n\n	return true, "Игрок арестован"\nend\n\nfunction WantedSystem:Tick(deltaTime)\n	for userId, entry in pairs(wantedPlayers) do\n		if not entry.found then\n			entry.timer -= deltaTime\n			if entry.timer <= 0 then\n				self:RemoveWanted(entry.player)\n			end\n		else\n			entry.kpzDuration -= deltaTime\n			if entry.kpzDuration <= 0 then\n				entry.player:SetAttribute("InKPZ", false)\n				entry.player:SetAttribute("KPZTimer", 0)\n				wantedPlayers[userId] = nil\n			end\n		end\n	end\nend\n\nfunction WantedSystem:GetWantedPlayers()\n	local result = {}\n	for userId, entry in pairs(wantedPlayers) do\n		if not entry.found then\n			table.insert(result, {\n				player = entry.player,\n				timer = entry.timer,\n			})\n		end\n	end\n	return result\nend\n\nfunction WantedSystem:IsWanted(player)\n	return wantedPlayers[player.UserId] ~= nil\nend\n\nfunction WantedSystem:OnPlayerRemoving(player)\n	wantedPlayers[player.UserId] = nil\nend\n\nreturn WantedSystem\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'BriefcaseSystem', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\n\nlocal BriefcaseSystem = {}\nBriefcaseSystem.__index = BriefcaseSystem\n\nlocal cooldowns = {}\n\nlocal weaponPool = {\n	"Pistol",\n	"Shotgun",\n	"SMG",\n	"Rifle",\n}\n\nfunction BriefcaseSystem:Use(briefcaseTool, supplierPlayer, targetPlayer)\n	local supplierId = supplierPlayer.UserId\n\n	if cooldowns[supplierId] then\n		return false, "Перезарядка"\n	end\n\n	if not targetPlayer or not targetPlayer.Character then\n		return false, "Цель не найдена"\n	end\n\n	local distance = (supplierPlayer.Character:GetPivot().Position - targetPlayer.Character:GetPivot().Position).Magnitude\n	if distance > 5 then\n		return false, "Слишком далеко"\n	end\n\n	local randomWeapon = weaponPool[math.random(1, #weaponPool)]\n\n	local weaponTemplate = ReplicatedStorage:FindFirstChild("Weapons"):FindFirstChild(randomWeapon)\n	if weaponTemplate then\n		local weaponClone = weaponTemplate:Clone()\n		weaponClone.Parent = targetPlayer.Backpack\n	end\n\n	cooldowns[supplierId] = true\n	task.delay(Config.BRIEFCASE_COOLDOWN, function()\n		cooldowns[supplierId] = nil\n	end)\n\n	return true, "Оружие выдано: " .. randomWeapon\nend\n\nfunction BriefcaseSystem:IsOnCooldown(player)\n	return cooldowns[player.UserId] == true\nend\n\nfunction BriefcaseSystem:GetCooldownRemaining(player)\n	if not cooldowns[player.UserId] then return 0 end\n	return Config.BRIEFCASE_COOLDOWN\nend\n\nfunction BriefcaseSystem:OnPlayerRemoving(player)\n	cooldowns[player.UserId] = nil\nend\n\nreturn BriefcaseSystem\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'ManagerComputer', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Players = game:GetService("Players")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\nlocal DataStore = require(ReplicatedStorage.Modules.DataStore)\nlocal WantedSystem = require(script.Parent.WantedSystem)\n\nlocal ManagerComputer = {}\nManagerComputer.__index = ManagerComputer\n\nfunction ManagerComputer:FireEmployee(managerPlayer, targetName, reason)\n	if managerPlayer:GetAttribute("CurrentRole") ~= "Manager" then\n		return false, "Нет доступа"\n	end\n\n	local target = Players:FindFirstChild(targetName)\n	if not target then\n		return false, "Игрок не найден"\n	end\n\n	local targetRole = target:GetAttribute("CurrentRole")\n	if not targetRole then\n		return false, "Игрок без роли"\n	end\n\n	local DataStoreModule = require(ReplicatedStorage.Modules.DataStore)\n	DataStoreModule:FireEmployee(target, targetRole)\n\n	target:SetAttribute("CurrentRole", nil)\n	target:SetAttribute("CurrentCard", nil)\n	target:SetAttribute("AccessLevel", 0)\n\n	return true, targetName .. " уволен"\nend\n\nfunction ManagerComputer:DeclareWanted(managerPlayer, targetName, reason, duration)\n	if managerPlayer:GetAttribute("CurrentRole") ~= "Manager" then\n		return false, "Нет доступа"\n	end\n\n	local target = Players:FindFirstChild(targetName)\n	if not target then\n		return false, "Игрок не найден"\n	end\n\n	local success, msg = WantedSystem:DeclareWanted(target, managerPlayer, duration)\n	return success, msg\nend\n\nfunction ManagerComputer:IssueWarning(managerPlayer, targetName, reason)\n	if managerPlayer:GetAttribute("CurrentRole") ~= "Manager" then\n		return false, "Нет доступа"\n	end\n\n	local target = Players:FindFirstChild(targetName)\n	if not target then\n		return false, "Игрок не найден"\n	end\n\n	DataStore:Update(target, function(data)\n		data.warnings += 1\n		table.insert(data.punishments, {\n			type = "warning",\n			reason = reason,\n			time = os.time(),\n		})\n	end)\n\n	return true, "Выговор выдан " .. targetName\nend\n\nfunction ManagerComputer:GiveBonus(managerPlayer, targetName, amount, reason)\n	if managerPlayer:GetAttribute("CurrentRole") ~= "Manager" then\n		return false, "Нет доступа"\n	end\n\n	amount = math.clamp(amount, 0, Config.PREMIUM_LIMIT)\n\n	local target = Players:FindFirstChild(targetName)\n	if not target then\n		return false, "Игрок не найден"\n	end\n\n	DataStore:AddCiphers(target, amount)\n\n	return true, "Премия " .. amount .. " шифров выдана " .. targetName\nend\n\nreturn ManagerComputer\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'SurveillanceSystem', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\n\nlocal SurveillanceSystem = {}\nSurveillanceSystem.__index = SurveillanceSystem\n\nlocal cameraStates = {}\nlocal shieldStates = {}\n\nfunction SurveillanceSystem:Init()\n	for _, obj in ipairs(workspace:GetDescendants()) do\n		if obj:IsA("BasePart") and obj:GetAttribute("CameraId") then\n			cameraStates[obj:GetAttribute("CameraId")] = {\n				part = obj,\n				active = true,\n			}\n		end\n		if obj:IsA("BasePart") and obj:GetAttribute("ShieldId") then\n			shieldStates[obj:GetAttribute("ShieldId")] = {\n				part = obj,\n				intact = true,\n			}\n		end\n	end\nend\n\nfunction SurveillanceSystem:ActivateCamera(player, cameraId)\n	local camData = cameraStates[cameraId]\n	if not camData or not camData.active then return false end\n\n	local camPart = camData.part\n	if camPart then\n		player.Camera.CameraType = Enum.CameraType.Scriptable\n		player.Camera.CFrame = camPart.CFrame * CFrame.new(0, 0, -5)\n		player.Camera.CFrame = CFrame.lookAt(player.Camera.CFrame.Position, camPart.Position)\n	end\n\n	return true\nend\n\nfunction SurveillanceSystem:DeactivateCamera(player)\n	player.Camera.CameraType = Enum.CameraType.Custom\nend\n\nfunction SurveillanceSystem:GetAllCameras()\n	local list = {}\n	for id, data in pairs(cameraStates) do\n		if data.active then\n			table.insert(list, {\n				id = id,\n				part = data.part,\n			})\n		end\n	end\n	return list\nend\n\nfunction SurveillanceSystem:BreakShield(shieldId)\n	local shield = shieldStates[shieldId]\n	if shield then\n		shield.intact = false\n		ReplicatedStorage:SetAttribute("Shield_" .. shieldId, false)\n	end\nend\n\nfunction SurveillanceSystem:RepairShield(player, shieldId)\n	local shield = shieldStates[shieldId]\n	if not shield or shield.intact then return false end\n\n	local tool = player.Character and player.Character:FindFirstChild("Toolbox")\n	if not tool then return false, "Нет инструментов" end\n\n	shield.intact = true\n	ReplicatedStorage:SetAttribute("Shield_" .. shieldId, true)\n	return true, "Щиток починен"\nend\n\nfunction SurveillanceSystem:InteractShield(player, shieldId)\n	local shield = shieldStates[shieldId]\n	if not shield then return false end\n\n	if shield.intact then\n		return false, "Щиток уже работает"\n	end\n\n	if player:GetAttribute("CurrentRole") ~= "Technician" then\n		return false, "Только техник может чинить"\n	end\n\n	local tool = player.Character and player.Character:FindFirstChild("Toolbox")\n	if not tool then return false, "Возьмите коробку с инструментами" end\n\n	return self:RepairShield(player, shieldId)\nend\n\nreturn SurveillanceSystem\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'HealthSystem', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Players = game:GetService("Players")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\n\nlocal HealthSystem = {}\nHealthSystem.__index = HealthSystem\n\nlocal activeAdrenaline = {}\n\nfunction HealthSystem:UseMedkit(player)\n	local character = player.Character\n	if not character then return false end\n\n	local humanoid = character:FindFirstChildOfClass("Humanoid")\n	if not humanoid then return false end\n\n	if humanoid.Health >= humanoid.MaxHealth then\n		return false, "Полное здоровье"\n	end\n\n	humanoid.Health = math.min(humanoid.Health + Config.MEDKIT_HEAL, humanoid.MaxHealth)\n\n	return true, "Аптечка использована"\nend\n\nfunction HealthSystem:UseAdrenaline(player)\n	local userId = player.UserId\n	if activeAdrenaline[userId] then\n		return false, "Адреналин уже активен"\n	end\n\n	local character = player.Character\n	if not character then return false end\n\n	local humanoid = character:FindFirstChildOfClass("Humanoid")\n	if not humanoid then return false end\n\n	local walkSpeed = humanoid.WalkSpeed\n	humanoid.WalkSpeed = walkSpeed * Config.ADRENALINE_SPEED_MULT\n\n	activeAdrenaline[userId] = true\n\n	task.delay(Config.ADRENALINE_DURATION, function()\n		activeAdrenaline[userId] = nil\n		if character and character.Parent then\n			local h = character:FindFirstChildOfClass("Humanoid")\n			if h then\n				h.WalkSpeed = walkSpeed\n			end\n		end\n	end)\n\n	return true, "Адреналин активирован"\nend\n\nfunction HealthSystem:OnPlayerRemoving(player)\n	activeAdrenaline[player.UserId] = nil\nend\n\nreturn HealthSystem\n')
ensureModule(SSS:WaitForChild('Server'):WaitForChild('System'), 'VirologySystem', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Players = game:GetService("Players")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\n\nlocal VirologySystem = {}\nVirologySystem.__index = VirologySystem\n\nlocal activeMutations = {}\n\nfunction VirologySystem:OfferPill(scientistPlayer, targetPlayer, isForced)\n	if not targetPlayer or not targetPlayer.Character then return false, "Цель не найдена" end\n\n	local role = scientistPlayer:GetAttribute("CurrentRole")\n	if role ~= "ResearcherLab" and role ~= "ResearcherChem" then\n		return false, "Нет доступа"\n	end\n\n	if isForced then\n		return self:ApplyPill(targetPlayer, scientistPlayer)\n	end\n\n	ReplicatedStorage:SetAttribute("PillOffer_" .. targetPlayer.UserId, true)\n	ReplicatedStorage:SetAttribute("PillOfferer_" .. targetPlayer.UserId, scientistPlayer.UserId)\n\n	return true, "Предложение таблетки"\nend\n\nfunction VirologySystem:AcceptPill(targetPlayer)\n	local offerKey = "PillOffer_" .. targetPlayer.UserId\n	local offererKey = "PillOfferer_" .. targetPlayer.UserId\n\n	ReplicatedStorage:SetAttribute(offerKey, false)\n	local offererId = ReplicatedStorage:GetAttribute(offererKey)\n	ReplicatedStorage:SetAttribute(offererKey, nil)\n\n	local offerer = Players:GetPlayerByUserId(offererId)\n	return self:ApplyPill(targetPlayer, offerer)\nend\n\nfunction VirologySystem:DeclinePill(targetPlayer)\n	ReplicatedStorage:SetAttribute("PillOffer_" .. targetPlayer.UserId, false)\n	ReplicatedStorage:SetAttribute("PillOfferer_" .. targetPlayer.UserId, nil)\nend\n\nfunction VirologySystem:ApplyPill(targetPlayer, sourcePlayer)\n	local role = sourcePlayer and sourcePlayer:GetAttribute("CurrentRole")\n	if role ~= "ResearcherLab" and role ~= "ResearcherChem" then\n		return false, "Нет доступа"\n	end\n\n	local userId = targetPlayer.UserId\n	if activeMutations[userId] then return false, "Уже в процессе" end\n\n	activeMutations[userId] = true\n\n	task.delay(Config.Virology.TABLET_MUTATION_DELAY, function()\n		activeMutations[userId] = nil\n		if targetPlayer and targetPlayer.Parent then\n			targetPlayer:SetAttribute("IsMutating", true)\n			ReplicatedStorage:SetAttribute("Mutation_" .. userId, true)\n\n			task.delay(30, function()\n				targetPlayer:SetAttribute("IsMutating", false)\n				ReplicatedStorage:SetAttribute("Mutation_" .. userId, false)\n			end)\n		end\n	end)\n\n	return true, "Таблетка применена"\nend\n\nfunction VirologySystem:InjectSyringe(scientistPlayer, targetPlayer)\n	if not targetPlayer or not targetPlayer.Character then return false, "Цель не найдена" end\n\n	local role = scientistPlayer:GetAttribute("CurrentRole")\n	if role ~= "ResearcherChem" then\n		return false, "Только химик"\n	end\n\n	local distance = (scientistPlayer.Character:GetPivot().Position - targetPlayer.Character:GetPivot().Position).Magnitude\n	if distance > 5 then\n		return false, "Слишком далеко"\n	end\n\n	local syringeType = scientistPlayer:GetAttribute("HeldSyringeType") or "virus"\n\n	targetPlayer:SetAttribute("SyringeEffect_" .. syringeType, true)\n	ReplicatedStorage:SetAttribute("SyringeEffect_" .. targetPlayer.UserId .. "_" .. syringeType, true)\n\n	task.delay(10, function()\n		targetPlayer:SetAttribute("SyringeEffect_" .. syringeType, false)\n		ReplicatedStorage:SetAttribute("SyringeEffect_" .. targetPlayer.UserId .. "_" .. syringeType, false)\n	end)\n\n	return true, "Шприц введён"\nend\n\nfunction VirologySystem:UseAntidote(scientistPlayer, targetPlayer)\n	if not targetPlayer or not targetPlayer.Character then return false, "Цель не найдена" end\n\n	local role = scientistPlayer:GetAttribute("CurrentRole")\n	if role ~= "ResearcherChem" then\n		return false, "Только химик"\n	end\n\n	targetPlayer:SetAttribute("IsMutating", false)\n	ReplicatedStorage:SetAttribute("Mutation_" .. targetPlayer.UserId, false)\n\n	for effectType, _ in pairs(Config.Virology.ANTIDOTE_EFFECTS) do\n		targetPlayer:SetAttribute("SyringeEffect_" .. effectType, false)\n		ReplicatedStorage:SetAttribute("SyringeEffect_" .. targetPlayer.UserId .. "_" .. effectType, false)\n	end\n\n	return true, "Антидот применён"\nend\n\nfunction VirologySystem:OnPlayerRemoving(player)\n	activeMutations[player.UserId] = nil\nend\n\nreturn VirologySystem\n')
